   k=min(n,160); ids=np.argpartition(M,k-1,axis=1)[:,:k].astype(np.int64); c=np.ascontiguousarray(np.take_along_axis(M,ids,axis=1));ids=np.ascontiguousarray(ids);o=np.empty(n,np.int32);p=np.empty(n);F(c,ids,n,k,o,p)
