// epsilon-scaling auction for square minimum assignment
int auction(const double *c, int n, int *asgn) {
 double *p=(double*)calloc(n,sizeof(double));
 int *owner=(int*)malloc(n*sizeof(int));
 int *stack=(int*)malloc(n*sizeof(int));
 if(!p||!owner||!stack) return -1;
 double eps=0.2;
 while(eps > 2e-13) {
   eps *= 0.2;
   for(int j=0;j<n;j++) owner[j]=-1;
   int top=n;
   for(int i=0;i<n;i++) stack[i]=i;
   while(top) {
     int i=stack[--top]; const double *row=c+(size_t)i*n;
     double v1=DBL_MAX,v2=DBL_MAX; int bj=-1;
     for(int j=0;j<n;j++) {
       double v=row[j]+p[j];
       if(v<v1) {v2=v1;v1=v;bj=j;} else if(v<v2) v2=v;
     }
     p[bj] += (v2-v1)+eps;
     int old=owner[bj]; owner[bj]=i; asgn[i]=bj;
     if(old>=0) stack[top++]=old;
   }
 }
 free(p);free(owner);free(stack);return 0;
}
